import { builder } from './builder';
import './types/user';
import './types/post';
import './types/attachments';
import './types/viewer';
import './queries';

export const schema = builder.toSchema();

import SchemaBuilder from '@pothos/core';
import DrizzlePlugin from '@pothos/plugin-drizzle';
import RelayPlugin from '@pothos/plugin-relay';
import { getTableConfig } from 'drizzle-orm/sqlite-core';
import { db } from './database';
import { relations } from './tables';

export const builder = new SchemaBuilder<{
  DrizzleRelations: typeof relations;
  Context: { userId: number };
}>({
  relay: { nodesOnConnection: true },
  plugins: [RelayPlugin, DrizzlePlugin],
  drizzle: { client: db, relations, getTableConfig },
});

import { drizzle, type SqliteProxyExecutors } from 'drizzle-orm/sqlite-proxy';
import initSqlJs, { type QueryExecResult, type SqlValue } from 'sql.js';
import { relations } from './tables';

// sql.js executes real SQLite in WebAssembly. Keep the serialized database
// with this schema, so rebuilding/resetting the schema also resets its data.
// Closing each connection releases WASM memory even when an example is replaced.
const sqlite = initSqlJs({
  locateFile: (file: string) => `https://cdn.jsdelivr.net/npm/sql.js@1.14.1/dist/${file}`,
});
let saved: Uint8Array | undefined;
const seed = `
PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY, firstName TEXT NOT NULL, lastName TEXT NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL);
CREATE TABLE profiles (id INTEGER PRIMARY KEY, userId INTEGER NOT NULL UNIQUE REFERENCES users(id), bio TEXT);
CREATE TABLE posts (id INTEGER PRIMARY KEY, authorId INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, content TEXT NOT NULL, published INTEGER NOT NULL, createdAt TEXT NOT NULL);
CREATE TABLE media (id INTEGER PRIMARY KEY, url TEXT NOT NULL, uploadedById INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE postMedia (id INTEGER PRIMARY KEY, postId INTEGER NOT NULL REFERENCES posts(id), mediaId INTEGER NOT NULL REFERENCES media(id), caption TEXT, UNIQUE(postId, mediaId));
INSERT INTO users VALUES (1, 'Maya', 'Chen', 'maya@example.com', 'editor'), (2, 'Leo', 'Silva', 'leo@example.com', 'author'), (3, 'Nora', 'Ellis', 'nora@example.com', 'author');
INSERT INTO profiles VALUES (1, 1, 'Writes about community gardens.');
INSERT INTO posts VALUES
(1, 1, 'Starting a seed library', 'Share seeds with your neighbors.', 1, '2026-01-15T09:00:00.000Z'),
(2, 1, 'A guide to composting', 'Turn kitchen scraps into healthy soil.', 1, '2026-01-15T09:00:00.000Z'),
(3, 2, 'Watering through summer', 'Water early and mulch deeply.', 1, '2026-01-15T09:00:00.000Z'),
(5, 2, 'Saving rainwater', 'Leo’s unpublished draft.', 0, '2026-01-15T09:00:00.000Z'),
(4, 1, 'Planning the spring exchange', 'An unpublished editorial draft.', 0, '2026-01-15T09:00:00.000Z');
INSERT INTO media VALUES
(1, 'https://images.example.com/seed-library.jpg', 2),
(2, 'https://images.example.com/compost.jpg', 1),
(3, 'https://images.example.com/mulch.jpg', 1);
INSERT INTO postMedia VALUES
(1, 1, 1, 'The neighborhood seed exchange'),
(2, 2, 1, 'Seeds and soil at the community garden'),
(3, 2, 2, 'Finished compost ready for planting'),
(4, 2, 3, NULL);
`;

async function execute(sql: string, params: SqlValue[]): Promise<QueryExecResult> {
  const SQL = await sqlite;
  const connection = new SQL.Database(saved);
  try {
    if (!saved) {
      connection.run(seed);
    }
    connection.run('PRAGMA foreign_keys = ON');
    console.log('SQL', sql, params);
    const result = connection.exec(sql, params);
    saved = connection.export();
    return result[0] ?? { columns: [], values: [] };
  } finally {
    connection.close();
  }
}

// Drizzle asks for rows as arrays by default, or as objects keyed by column for raw queries.
function shapeRows({ columns, values }: QueryExecResult, rowMode?: 'array' | 'object') {
  return rowMode === 'object'
    ? values.map((row) => Object.fromEntries(columns.map((column, i) => [column, row[i]])))
    : values;
}

export const db = drizzle(
  {
    all: async (sql: string, params: SqlValue[], rowMode?: 'array' | 'object') =>
      shapeRows(await execute(sql, params), rowMode),
    get: async (sql: string, params: SqlValue[], rowMode?: 'array' | 'object') =>
      shapeRows(await execute(sql, params), rowMode)[0],
    run: execute,
  } as SqliteProxyExecutors,
  { relations },
);

import { eq } from 'drizzle-orm';
import { builder } from './builder';
import { db } from './database';
import { posts } from './tables';
import { Viewer } from './types/viewer';

builder.queryType({
  fields: (t) => ({
    author: t.drizzleField({
      type: 'users',
      nullable: true,
      args: { id: t.arg.int({ required: true }) },
      resolve: (query, _root, args) => {
        return db.query.users.findFirst(
          query({
            where: { id: args.id },
          }),
        );
      },
    }),
  }),
});

builder.queryFields((t) => ({
  me: t.drizzleField({
    type: Viewer,
    nullable: true,
    resolve: (query, _root, _args, ctx) => {
      return db.query.users.findFirst(
        query({
          where: { id: ctx.userId },
        }),
      );
    },
  }),
  posts: t.drizzleConnection({
    type: 'posts',
    totalCount: () => {
      return db.$count(posts, eq(posts.published, true));
    },
    resolve: (query) => {
      return db.query.posts.findMany(
        query({
          where: { published: true },
          // Three posts share this timestamp. Pothos adds the primary key
          // to the cursor ordering, so traversing pages still visits each once.
          orderBy: { createdAt: 'desc' },
        }),
      );
    },
  }),
}));

import { defineRelations } from 'drizzle-orm';
import { integer, sqliteTable, text, unique } from 'drizzle-orm/sqlite-core';

export const users = sqliteTable('users', {
  id: integer().primaryKey(),
  firstName: text().notNull(),
  lastName: text().notNull(),
  email: text().notNull().unique(),
  role: text({ enum: ['editor', 'author'] }).notNull(),
});
export const profiles = sqliteTable('profiles', {
  id: integer().primaryKey(),
  userId: integer()
    .notNull()
    .unique()
    .references(() => users.id),
  bio: text(),
});
export const posts = sqliteTable('posts', {
  id: integer().primaryKey(),
  authorId: integer()
    .notNull()
    .references(() => users.id),
  title: text().notNull(),
  content: text().notNull(),
  published: integer({ mode: 'boolean' }).notNull(),
  createdAt: text().notNull(),
});
export const media = sqliteTable('media', {
  id: integer().primaryKey(),
  url: text().notNull(),
  uploadedById: integer()
    .notNull()
    .references(() => users.id),
});
export const postMedia = sqliteTable(
  'postMedia',
  {
    caption: text(),
    id: integer().primaryKey(),
    postId: integer()
      .notNull()
      .references(() => posts.id),
    mediaId: integer()
      .notNull()
      .references(() => media.id),
  },
  (table) => [unique().on(table.postId, table.mediaId)],
);

export const relations = defineRelations({ users, profiles, posts, media, postMedia }, (r) => ({
  users: {
    profile: r.one.profiles({ from: r.users.id, to: r.profiles.userId }),
    posts: r.many.posts({ from: r.users.id, to: r.posts.authorId }),
  },
  profiles: { user: r.one.users({ from: r.profiles.userId, to: r.users.id, optional: false }) },
  posts: {
    attachments: r.many.postMedia({ from: r.posts.id, to: r.postMedia.postId }),
    author: r.one.users({ from: r.posts.authorId, to: r.users.id, optional: false }),
    media: r.many.media({
      from: r.posts.id.through(r.postMedia.postId),
      to: r.media.id.through(r.postMedia.mediaId),
    }),
  },
  postMedia: {
    media: r.one.media({ from: r.postMedia.mediaId, to: r.media.id, optional: false }),
  },
  media: {
    uploadedBy: r.one.users({ from: r.media.uploadedById, to: r.users.id, optional: false }),
  },
}));

import { drizzleConnectionHelpers } from '@pothos/plugin-drizzle';
import { builder } from '../builder';
import { Media } from './post';

const attachmentArgs = builder.args((t) => ({
  hasCaption: t.boolean({ defaultValue: false }),
}));

const attachments = drizzleConnectionHelpers(builder, 'postMedia', {
  args: () => attachmentArgs,
  query: (args) => ({
    orderBy: { id: 'asc' },
    where: args.hasCaption ? { caption: { isNotNull: true } } : {},
  }),
  select: (nestedSelection) => {
    return {
      columns: { caption: true },
      with: { media: nestedSelection() },
    };
  },
  resolveNode: (attachment) => attachment.media,
});

builder.drizzleObjectField('posts', 'attachments', (t) =>
  t.connection(
    {
      type: Media,
      args: attachments.getArgs(),
      select: (args, ctx, nestedSelection) => {
        return {
          with: {
            attachments: attachments.getQuery(args, ctx, nestedSelection),
          },
        };
      },
      resolve: (post, args, ctx) => {
        return attachments.resolve(post.attachments, args, ctx);
      },
    },
    {},
    {
      fields: (edge) => ({
        caption: edge.string({
          nullable: true,
          resolve: (attachment) => attachment.caption,
        }),
      }),
    },
  ),
);

import { builder } from '../builder';

builder.drizzleObject('posts', {
  name: 'Post',
  select: {},
  fields: (t) => ({
    id: t.exposeID('id'),
    title: t.exposeString('title'),
    author: t.relation('author'),
    media: t.relation('media'),
    mediaConnection: t.relatedConnection('media', {
      query: { orderBy: { id: 'asc' } },
      totalCount: true,
    }),
  }),
});
export const Media = builder.drizzleObject('media', {
  name: 'Media',
  fields: (t) => ({ url: t.exposeString('url'), uploadedBy: t.relation('uploadedBy') }),
});

import { eq } from 'drizzle-orm';
import { builder } from '../builder';
import { posts } from '../tables';

builder.drizzleNode('users', {
  name: 'User',
  id: { column: (user) => user.id },
  select: {},
  fields: (t) => ({
    firstName: t.exposeString('firstName'),
    fullName: t.string({
      select: { columns: { firstName: true, lastName: true } },
      resolve: (user) => `${user.firstName} ${user.lastName}`,
    }),
    lowercaseName: t.string({
      select: {
        extras: {
          lowercaseName: (users, { sql }) => sql<string>`lower(${users.firstName})`,
        },
      },
      resolve: (user) => user.lowercaseName,
    }),
    bio: t.string({
      nullable: true,
      select: { with: { profile: true } },
      resolve: (user) => user.profile?.bio,
    }),
    posts: t.relation('posts', {
      args: { oldestFirst: t.arg.boolean() },
      query: (args) => ({
        where: { published: true },
        orderBy: {
          createdAt: args.oldestFirst ? 'asc' : 'desc',
          id: args.oldestFirst ? 'asc' : 'desc',
        },
      }),
    }),
    postCount: t.relatedCount('posts', { where: eq(posts.published, true) }),
    postsConnection: t.relatedConnection('posts', {
      query: { where: { published: true }, orderBy: { createdAt: 'desc' } },
      totalCount: true,
    }),
  }),
});

import { builder } from '../builder';

export const Viewer = builder.drizzleInterface('users', {
  variant: 'Viewer',
  select: { columns: { id: true, role: true } },
  resolveType: (user) => (user.role === 'editor' ? 'EditorViewer' : 'AuthorViewer'),
  fields: (t) => ({
    user: t.variant('users'),
    email: t.exposeString('email'),
    drafts: t.relation('posts', {
      query: { where: { published: false }, orderBy: { id: 'asc' } },
    }),
  }),
});
builder.drizzleObject('users', {
  variant: 'EditorViewer',
  interfaces: [Viewer],
  select: { columns: { id: true, role: true } },
  fields: (t) => ({ canReviewSubmissions: t.boolean({ resolve: () => true }) }),
});
builder.drizzleObject('users', {
  variant: 'AuthorViewer',
  interfaces: [Viewer],
  select: { columns: { id: true, role: true } },
});

builder.drizzleObjectField('users', 'viewer', (t) =>
  t.variant(Viewer, {
    select: { columns: { id: true } },
    isNull: (user, _args, ctx) => user.id !== ctx.userId,
  }),
);

