# Compare the newest and oldest selections in Queries, then inspect their SQL in Console.
query Aliases {
  author(id: 1) {
    newest: posts {
      title
    }
    oldest: posts(oldestFirst: true) {
      title
    }
  }
}

# Change userId to 2 in Context to see the other viewer and their drafts.
query Viewer {
  me {
    __typename
    email
    user {
      fullName
    }
    drafts {
      title
    }
    ... on EditorViewer {
      canReviewSubmissions
    }
  }
}

# To load the next page, copy pageInfo.endCursor into after in Variables and run again.
query Pagination($after: String) {
  posts(first: 2, after: $after) {
    totalCount
    nodes {
      title
      media {
        url
        uploadedBy {
          fullName
        }
      }
    }
    pageInfo {
      startCursor
      endCursor
      hasNextPage
      hasPreviousPage
    }
  }
}

query Missing {
  author(id: 3) {
    bio
    posts {
      title
    }
    postCount
  }
  missing: author(id: 999) {
    fullName
  }
}

query RelatedPages {
  author(id: 1) {
    postsConnection(first: 1) {
      totalCount
      nodes {
        title
        mediaConnection(first: 1) {
          totalCount
          nodes {
            url
          }
        }
      }
      pageInfo {
        hasNextPage
      }
    }
  }
}

query RefetchAuthor {
  node(id: "VXNlcjox") {
    ... on User {
      fullName
      posts {
        title
      }
    }
  }
}

# Change userId to 2 in Context to see which author exposes private viewer fields.
query PrivateVariant {
  own: author(id: 1) {
    viewer {
      email
      drafts {
        title
      }
    }
  }
  other: author(id: 2) {
    viewer {
      email
      drafts {
        title
      }
    }
  }
}

# Set hasCaption to true in Variables to keep only captioned attachments.
# To load the next attachment page, copy its pageInfo.endCursor into after in Variables.
query Attachments($after: String, $hasCaption: Boolean = false) {
  author(id: 1) {
    postsConnection(first: 1) {
      nodes {
        title
        attachments(first: 2, after: $after, hasCaption: $hasCaption) {
          edges {
            caption
            node {
              url
              uploadedBy {
                fullName
              }
            }
          }
          pageInfo {
            startCursor
            endCursor
            hasNextPage
            hasPreviousPage
          }
        }
      }
    }
  }
}
